//! Explicit full generator consumers under current operation control.
//! Only original-data loans are accepted; no finite-role promotion or installer.
use super::*;
use generator_policy::GeneratorName;
type BodyBorrower<'a>=dyn Fn(&Arc<dm_tree::frontend::BodySyntaxInput>)->Result<Arc<dm_tree::frontend::BodySyntax>,dm_tree::frontend::BodySyntaxFailure>+'a;
use super::super::workspace::WorkspaceGeneratorTestWitness;
use dq_analyze::{captured_raw_file::Config as RawConfig,generator_test_scope::TestTypeCollector,key_policy_control::Control};
pub(in crate::query_db) struct Artifact{value:generator_policy::Artifact,capture:Weak<CapturedPolicyInputs>,code:WorkspaceCodeWitness,tests:WorkspaceGeneratorTestWitness}
impl Artifact{
 pub(super) fn output(&self)->&generator_policy::Artifact{&self.value}
 pub(in crate::query_db) fn retained_charge(&self)->Option<usize>{let mut bytes=self.value.charge().checked_add(std::mem::size_of::<Self>())?.checked_add(std::mem::size_of::<CapturedPolicyInputs>()+2*std::mem::size_of::<usize>());self.code.visit_storage(|_,n|bytes=bytes.and_then(|old|old.checked_add(n)));self.tests.visit_storage(|_,n|bytes=bytes.and_then(|old|old.checked_add(n)));bytes}
 pub(in crate::query_db) fn fingerprint(&self)->u128{self.value.fingerprint()}
 pub(super) fn matches(&self,name:GeneratorName,loan:&super::super::reactive_workspace_operation::Loan,scope:&crate::runner_host::query_snapshot::workspace_native_guard::NativeReadGuard<'_>)->Result<bool,Failure>{let Some(capture)=self.capture.upgrade()else{return Ok(false)};Ok(Arc::ptr_eq(&capture,&loan.capture)&&self.value.name==name&&self.code.matches(&loan.workspace,scope,loan.capture.policy())?&&self.tests.matches(&loan.workspace,scope,loan.capture.policy())?)}
}
struct Temporary{budget:Arc<Budget>,success:bool}
impl Temporary{fn new(parent:&Arc<Budget>)->Result<Self,Failure>{Ok(Self{budget:Budget::scoped_temporaries(parent).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?,success:false})}}
impl Drop for Temporary{fn drop(&mut self){if !self.success{self.budget.keep_failed_scratch()}}}
struct Tests{rows:Option<std::collections::BTreeSet<String>>,witness:Option<WorkspaceGeneratorTestWitness>,scratch:Temporary}
impl Drop for Tests{fn drop(&mut self){drop(self.rows.take());drop(self.witness.take());}}
struct TestControl<'a>{budget:&'a Budget,poll:&'a dyn Fn()->io::Result<()>}
impl Control for TestControl<'_>{type Error=Failure;const CHECKED:bool=true;fn checkpoint(&mut self)->Result<(),Failure>{(self.poll)()?;self.budget.require().map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))}fn reserve(&mut self,bytes:usize)->Result<(),Failure>{self.budget.charge(bytes).map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))}fn overflow(&mut self)->Failure{self.budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"generator test rows admission overflow"))}fn allocation_failed(&mut self)->Failure{self.overflow()}}
fn tests(reader:&WorkspaceCodeReader<'_,'_>,inputs:&dm_analysis::policy_inputs::PolicyInputs,poll:&dyn Fn()->io::Result<()>)->Result<Tests,Failure>{let scratch=Temporary::new(reader.budget())?;let result=(||{let mut collector=TestTypeCollector::default();let mut control=TestControl{budget:&scratch.budget,poll};let completed=reader.for_each_generator_test_file_completed(inputs,&mut|relative,views|{collector.observe(relative,views.raw()?,&mut control)?;Ok(true)})?;let witness=completed.into_witness()?.ok_or_else(||Failure::Operational(io::Error::new(io::ErrorKind::InvalidData,"generator test traversal stopped before completion")))?;Ok::<_,Failure>((collector.finish(),witness))})();match result{Ok((rows,witness))=>Ok(Tests{rows:Some(rows),witness:Some(witness),scratch}),Err(actual)=>Err(actual)}}
fn output_diags_charge(rows:&Vec<dq_analyze::sparse_slots_policy::Diagnostic>)->Option<usize>{rows.capacity().checked_mul(std::mem::size_of::<dq_analyze::sparse_slots_policy::Diagnostic>()).and_then(|n|rows.iter().try_fold(n,|n,row|n.checked_add(row.rel.capacity())?.checked_add(row.msg.capacity())))}
fn named(name:GeneratorName,mut output:dq_analyze::sparse_slots_policy::Output,budget:&Arc<Budget>)->Result<generator_policy::Artifact,Failure>{let filename=match name{GeneratorName::Reads=>"reads.dm",GeneratorName::AutoTracked=>"auto_tracked.dm",GeneratorName::Deps=>"deps.dm",GeneratorName::SparseSlots=>"sparse_slots.dm",GeneratorName::DeclareIds=>"ids.dm",GeneratorName::Declare=>"declare.dm",GeneratorName::Plans=>"plans.dm",GeneratorName::Stats=>"stats.dm",GeneratorName::Actions=>"actions.dm",GeneratorName::TrackedLists=>"tracked_lists.dm",_=>return Err("named original generator role differs".into())};let text=output.captured_named_file_text(name.name(),filename,budget)?;Ok(generator_policy::Artifact{name,text,files:Vec::new(),diags:std::mem::take(&mut output.diags)})}
fn dependency_output(value:&Dependencies,name:GeneratorName,inputs:&dm_analysis::policy_inputs::PolicyInputs,budget:&Arc<Budget>)->Result<generator_policy::Artifact,Failure>{let mut scratch=Temporary::new(budget)?;let result=(||{let output=value.data.render_deps_data(inputs,&scratch.budget,&crate::daemon::control::checkpoint)?;let bytes=output_diags_charge(&output.diags).ok_or_else(||{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"dependency diagnostic retained capacity overflow"))})?;budget.charge(bytes)?;named(name,output,budget)})();scratch.success=result.is_ok();drop(scratch);result}
pub(super) fn produce_generator(name:GeneratorName,p:&Params,loan:&super::super::reactive_workspace_operation::Loan,reader:&WorkspaceCodeReader<'_,'_>,scope:&crate::runner_host::query_snapshot::workspace_native_guard::NativeReadGuard<'_>,pages:&Pages<'_,'_,'_>,order:&std::collections::HashMap<String,usize>,configuration:&RawConfig,dependencies:&dyn Fn(&mut dyn FnMut(&Dependencies)->Result<Value,Failure>)->Result<Value,Failure>,policy:&dyn reads::PolicyFactsProvider,provider:&dyn reads::RawPolicyReadProvider,poll:&dyn Fn()->io::Result<()>,body:&BodyBorrower<'_>)->Result<Value,Failure>{
 poll()?;if p.policy||!matches!(name,GeneratorName::Reads|GeneratorName::DerivedReads|GeneratorName::AutoTracked|GeneratorName::Deps|GeneratorName::SparseSlots|GeneratorName::DeclareIds|GeneratorName::Declare|GeneratorName::UiTypes|GeneratorName::Stats|GeneratorName::Actions|GeneratorName::SystemAccessors|GeneratorName::TrackedLists|GeneratorName::Plans){return Err("full generator role has not been ported".into())}
 let mut tests=tests(reader,loan.capture.policy(),poll)?;let mut completed_test=tests.witness.take();let rows=tests.rows.as_ref().expect("actual test traversal rows");let budget=reader.budget();
 let mut finish=|value:generator_policy::Artifact|->Result<Value,Failure>{poll()?;let code=match pages.witness.borrow_mut().take(){Some(witness)=>witness,None=>{let completed=reader.for_each_code_file_completed(loan.capture.policy(),&mut|_,_|Ok(true))?;completed.into_witness()?.ok_or_else(||Failure::Operational(io::Error::new(io::ErrorKind::InvalidData,"generator CODE traversal did not complete")))?}};if !code.matches(&loan.workspace,scope,loan.capture.policy())?{return Err("generator CODE proof differs".into())}let test_witness=completed_test.take().expect("single completed generator test role");budget.charge(std::mem::size_of::<Artifact>()+std::mem::size_of::<CapturedPolicyInputs>()+2*std::mem::size_of::<usize>())?;let artifact=Artifact{value,capture:Arc::downgrade(&loan.capture),code,tests:test_witness};Ok(Value::FullArtifact(artifact))};
 let result=match name{
  GeneratorName::Declare=>{let output=dq_analyze::captured_declare_pages::generate_from_pages(pages,order,budget,poll)?;finish(named(name,output,budget)?)},
  GeneratorName::SparseSlots|GeneratorName::DeclareIds=>{let role=if name==GeneratorName::SparseSlots{dq_analyze::captured_declaration_pages::Generator::SparseSlots}else{dq_analyze::captured_declaration_pages::Generator::DeclareIds};let output=dq_analyze::captured_declaration_pages::generate_from_pages(role,pages,order,budget,poll)?;finish(named(name,output,budget)?)},
  GeneratorName::TrackedLists=>{let output=dq_analyze::captured_tracked_lists_pages::generate_from_pages(loan.capture.policy(),reader.root(),pages,rows,budget,poll)?;finish(named(name,output,budget)?)},
  GeneratorName::SystemAccessors=>{let mut output=dq_analyze::captured_system_accessors_pages::generate_from_pages(pages,order,budget,poll)?;let text=output.captured_file_text(budget).map_err(|message|if budget.denied(){Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message))}else{Failure::Unsupported(message)})?;let diags=std::mem::take(&mut output.diags);drop(output);finish(generator_policy::Artifact{name,text,files:Vec::new(),diags})},
  GeneratorName::Actions=>{let output=dq_analyze::captured_actions_pages::generate_from_pages(pages,order,budget,poll)?;finish(named(name,output,budget)?)},
  GeneratorName::Stats=>{let output=dq_analyze::captured_stats_pages::generate_from_pages(pages,order,budget,poll)?;finish(named(name,output,budget)?)},
  GeneratorName::UiTypes=>{let files=dq_analyze::captured_ui_pages::generate_from_pages(pages,order,budget,poll)?;for(path,_)in &files.files{poll()?;budget.charge(reader.root().as_os_str().len().checked_add(path.len()).and_then(|n|n.checked_mul(8)).and_then(|n|n.checked_add(1024)).ok_or_else(||{budget.deny();Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"UI path validation admission overflow"))})?)?;generator_policy::validate_ui_output_path(reader.root(),path)?;}finish(generator_policy::Artifact{name,text:String::new(),files:files.files,diags:files.diags})},
  GeneratorName::Reads=>{let output=reads::render_reads_data_from_pages_with_policy(loan.capture.policy(),reader.root(),pages,order,rows,budget,provider,policy,poll,body)?;finish(named(name,output,budget)?)},
  GeneratorName::DerivedReads=>{let mut scratch=Temporary::new(budget)?;let funded=(||{let text=reads::render_derived_data_from_pages(loan.capture.policy(),reader.root(),pages,order,rows,&scratch.budget,poll,body)?;budget.charge(text.capacity())?;let path="code/_generated/reads.dm";budget.charge(4*path.len()+4*std::mem::size_of::<(String,String)>()+128)?;let mut files=Vec::new();files.try_reserve_exact(1).map_err(|actual|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,actual)))?;if files.capacity()>4{budget.deny();return Err(Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,"derived output directory exposed excess")))}files.push((path.to_owned(),text));Ok(generator_policy::Artifact{name,text:String::new(),files,diags:Vec::new()})})();scratch.success=funded.is_ok();drop(scratch);finish(funded?)},
  GeneratorName::Plans=>dependencies(&mut|value|{let output=value.data.render_plans_data_from_pages(loan.capture.policy(),reader.root(),pages,order,budget,poll)?;finish(named(name,output,budget)?) }),
  GeneratorName::Deps=>dependencies(&mut|value|finish(dependency_output(value,name,loan.capture.policy(),budget)?)),
  GeneratorName::AutoTracked=>dependencies(&mut|value|{let output=value.data.render_auto_data_from_pages(loan.capture.policy(),reader.root(),pages,order,configuration,&p.configuration_path,rows,budget,poll)?;finish(named(name,output,budget)?) }),_=>unreachable!()
 };tests.scratch.success=result.is_ok();drop(tests);if matches!(&result,Err(Failure::Operational(_))){return result}poll()?;budget.require().map_err(|message|Failure::Operational(io::Error::new(io::ErrorKind::OutOfMemory,message)))?;result
}
impl QueryDb{
 /// Explicit same-Db original generator loan. No stage installation or CLI
 /// cutover is granted; a later written frame requires a newly issued scope.
 pub(crate) fn with_workspace_generator<T>(&self,workspace:&Arc<WorkspaceCapture>,scope:&Arc<WorkspaceQueryScope>,capture:&Arc<CapturedPolicyInputs>,name:GeneratorName,consume:impl FnOnce(&generator_policy::Artifact)->io::Result<T>)->io::Result<T>{if !matches!(name,GeneratorName::Reads|GeneratorName::DerivedReads|GeneratorName::AutoTracked|GeneratorName::Deps|GeneratorName::SparseSlots|GeneratorName::DeclareIds|GeneratorName::Declare|GeneratorName::UiTypes|GeneratorName::Stats|GeneratorName::Actions|GeneratorName::SystemAccessors|GeneratorName::TrackedLists|GeneratorName::Plans){return Err(io::Error::new(io::ErrorKind::Unsupported,"full original generator is not selected"))}self.with_workspace_job_limit(workspace,scope,capture,Request::Dependencies,Some(name),None,|value|{let Value::FullArtifact(value)=value else{return Err(io::Error::new(io::ErrorKind::InvalidData,"full generator returned another role"))};consume(&value.value)})}
}
